QUESTÃO 16
hma pilha é uma estrutura de dados que armazena 
uma coleção de itens de dados relacionados e que 
garante o seguinte funcionamento:  o ultimo elemento 
a ser inserido é o primeiro a ser removido.   comum 
na  literatura  utilizar  os  nomes  push e pop  para  as 
operações de inserção e remoção de um elemento 
em uma pilha,  respectivamente.  K seguinte trecho 
de codigo em linguagem I defne uma estrutura de 
dados  pilha  utilizando  um  vetor  de  inteiros,   bem 
como algumas funções para sua manipulação.
#include <stdlib.h>
#include <stdio.h>
typedef struct {
      int elementos[100];
      int topo;
}pilha;
pilha * cria_pilha() {
      pilha * p =malloc(sizeof(pilha));
      p->topo = -1;
      return pilha;
}
void push(pilha *p, int elemento) {
      if (p->topo >= 99)
 return;
      p->elementos[++p->topo] = elemento;
}
int pop(pilha *p) {
      int a = p->elementos[p->topo];
      p->topo--;
      return a;
}

K programa a seguir utiliza uma pilha.
int main() {
      pilha * p = cria_pilha();
      push(p, 2);
      push(p, 3);
      push(p, 4);
      pop(p);
      push(p, 2);
      int a = pop(p) + pop(p);
      push(p, a);
      a += pop(p);
      printf(“%d”, a);
      return 0;
}
